+                $"{path} must name DCB {expectedVersion}.");
+            Assert(content.Contains(OrleansVersion, StringComparison.Ordinal),
+                $"{path} must retain the Orleans {OrleansVersion} support line.");
+            string scopeMarker;
+            if (kind == LibraryKind)
+            {
+                scopeMarker = "26";
+            }
+            else if (language == JapaneseLanguage)
+            {
+                scopeMarker = "テンプレート";
+            }
+            else
